#include <iostream>
#include <cstring>
#include <algorithm>
#include <cstdio>
#include <cmath>
using namespace std;

const int N = 100010;

int a[N];

int quick_sort(int q[], int l, int r, int k)
{
    //同快速排序
    int x = q[(l + r) / 2], i = l - 1, j = r + 1;
    if (l >= r) return q[l];
    while (i < j)
    {
        while (q[ ++ i] < x);
        while (q[ -- j] > x);
        if (i < j) swap(q[i], q[j]);
    }
    if (j - l + 1 >= k) return quick_sort(q, l, j, k); //第k小数在左边区间
    else return quick_sort(q, j + 1, r, k - (j - l + 1)); //第k小数在右边区间
}

int main()
{
    int n, k;
    scanf("%d%d", &n, &k);
    for (int i = 1; i <= n; i ++ ) scanf("%d", &a[i]);
    printf("%d", quick_sort(a, 1, n, k));
    return 0;
}
